// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes32 role, address account) public {
        vm.assume(account != address(0));

        // Domain: admissible inputs are SELF-renouncements: the caller renounces
        // a role for its own address (callerConfirmation == msg.sender).
        // General rule: an account may always renounce its own role — the call
        // renounceRole(role, account) issued by `account` itself MUST succeed
        // (the reference simply calls _revokeRole, which never reverts when the
        // role is not held either). The mutant inverts the guard and reverts
        // with AccessControlBadConfirmation on every such self-renouncement.

        vm.prank(account);
        bool ok;
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "self-renouncement must never revert");
    }
}
